package de.fitnesscoach.domain.plan;
import static org.junit.Assert.*;import java.time.*;import java.util.*;import org.junit.Test;import de.fitnesscoach.data.entity.*;
public class TrainingPlanEngineTest{@Test public void generatorRespectsAvailabilityAndAvoidsAdjacentIntensity(){UserProfileEntity p=new UserProfileEntity();p.fitnessLevel=DomainEnums.FitnessLevel.REGULAR;List<TrainingAvailabilityEntity>a=new ArrayList<>();for(int d=1;d<=7;d++){TrainingAvailabilityEntity x=new TrainingAvailabilityEntity();x.dayOfWeek=d;x.available=d==1||d==3||d==5||d==7;x.maxDurationMinutes=45;a.add(x);}TrainingPlanGenerator.Result r=new TrainingPlanGenerator().generate(LocalDate.of(2026,8,24),p,null,a,null);assertEquals(4,r.workouts.size());for(PlannedWorkoutEntity w:r.workouts)assertTrue(w.plannedDurationMinutes<=45);assertEquals(DomainEnums.Confidence.LOW,r.confidence);}@Test public void restRecoveryTurnsWorkoutIntoRest(){PlannedWorkoutEntity w=new PlannedWorkoutEntity();w.workoutType=DomainEnums.WorkoutType.INTERVAL;w.sportType=DomainEnums.SportType.RUNNING;w.plannedDurationMinutes=40;w.status=DomainEnums.WorkoutStatus.PLANNED;w.version=1;PlannedWorkoutEntity x=new DefaultPlanAdaptationPolicy().adapt(w,DomainEnums.RecoveryRecommendation.REST,null,null);assertEquals(DomainEnums.WorkoutType.REST,x.workoutType);assertEquals(DomainEnums.WorkoutStatus.ADAPTED,x.status);assertEquals(2,x.version);}@Test public void matcherAutoMatchesStrongSameDayCandidate(){LocalDate d=LocalDate.of(2026,8,26);WorkoutEntity a=new WorkoutEntity();a.startTime=d.atTime(8,0).atZone(ZoneId.systemDefault()).toInstant();a.sportType=DomainEnums.SportType.RUNNING;a.workoutType=DomainEnums.WorkoutType.EASY;a.durationMinutes=40;PlannedWorkoutEntity p=new PlannedWorkoutEntity();p.date=d;p.sportType=DomainEnums.SportType.RUNNING;p.workoutType=DomainEnums.WorkoutType.EASY;p.plannedDurationMinutes=40;p.status=DomainEnums.WorkoutStatus.PLANNED;WorkoutMatcher.Match m=new WorkoutMatcher().best(a,Collections.singletonList(p));assertEquals(WorkoutMatcher.MatchConfidence.HIGH,m.confidence);assertSame(p,m.planned);}}
